import { defineListener } from '@tsir/events';

import { UserRegisteredEvent } from '../events/user-registered.event.ts';

// Generated by `tsir make:listener`. Export it in the `listeners` array of the entry's
// `createEvents(...)`. Its payload is typed by UserRegisteredEvent.
export const SendWelcomeEmailListener = defineListener(UserRegisteredEvent, {
  // Unique within the event. It is part of the job name, so renaming it renames a job.
  name: 'send-welcome-email',
  handle(context) {
    // `context.id` is the idempotency key: stable across retries and relays.
    context.log(`send-welcome-email ${context.payload.id} (${context.id})`);
  },
});
